const SIGNATURES_FILE_HEADER = """
    # Generated by TrimTrace.record: one signature per line, checked by TrimTrace.check.
    # Delete a line to stop checking that signature.
    """

"""
    write_signatures(path, sigs)

Write `sigs` to `path`, one `Tuple{...}` expression per line in sorted order, so changes
between recordings show up as a readable diff.
"""
function write_signatures(path::AbstractString, sigs)
    open(path, "w") do io
        print(io, SIGNATURES_FILE_HEADER)
        for line in sort!(unique(string.(sigs)))
            println(io, line)
        end
    end
    return path
end

"""
    read_signatures(path) -> Vector{Expr}

Read the signatures stored by [`write_signatures`](@ref), skipping blank lines and `#`
comments.
"""
read_signatures(path::AbstractString) = Expr[Meta.parse(line) for line in _read_lines(path)]

# The stripped lines of `path`, without blank lines and `#` comments.
function _read_lines(path::AbstractString)
    lines = String[]
    for line in eachline(path)
        stripped = strip(line)
        (isempty(stripped) || startswith(stripped, '#')) && continue
        push!(lines, stripped)
    end
    return lines
end

"""
    uncovered(pkg::Module, sigs; exclude = Symbol[]) -> Vector{Symbol}

Return the public functions and types of `pkg` that no signature in `sigs` calls. Names
that are neither a function nor a type (constants, modules, macros) are not reported.
"""
function uncovered(pkg::Module, sigs; exclude = Symbol[])
    covered = Set{Symbol}(_signature_callee(sig) for sig in sigs)
    missing_names = Symbol[]
    for name in names(pkg)
        (name === nameof(pkg) || name in exclude || name in covered) && continue
        startswith(string(name), '@') && continue
        isdefined(pkg, name) || continue
        obj = getfield(pkg, name)
        obj isa Function || (obj isa Type && !isabstracttype(obj)) || continue
        push!(missing_names, name)
    end
    return sort!(missing_names)
end

# The unqualified callee name of a `Tuple{...}` signature expression.
function _signature_callee(sig::Expr)
    params = sig.args[2:end]
    ft = params[1] == :(typeof(Core.kwcall)) ? params[3] : params[1]
    target = ft.args[end]
    target = Meta.isexpr(target, :curly) ? target.args[1] : target
    return Meta.isexpr(target, :.) ? target.args[2].value : target
end
